import React from "react";
import "./Navbar.css";

function Navbar() {
return (
<nav className="navbar">
<div className="logo">
Medi<span>Vault</span> Pro
</div>
<ul className="nav-links">
<li><a href="/">Home</a></li>
<li><a href="/login">Login</a></li>
<li><a href="/register">Register</a></li>
</ul>
</nav>
);
}

export default Navbar;
